<?php $pageTitle='Doctor Schedule';require __DIR__.'/header.php';?><div class="head"><div><h1>My Schedule</h1><p>Dr. <?=htmlspecialchars($doctor['name'])?></p></div><form method="get"><input type="hidden" name="action" value="doctor_schedule"><input type="date" name="date" value="<?=$date?>"><button class="btn primary">View</button></form></div><section class="card table"><table><tr><th>Serial</th><th>Time</th><th>Patient</th><th>Status</th><th>Visit</th></tr><?php foreach($appointments as $a):?><tr><td>#<?=$a['serial_no']?></td><td><?=date('g:i A',strtotime($a['appointment_time']))?></td><td><?=htmlspecialchars($a['patient_name'])?><br><?=$a['patient_phone']?></td><td><span class="badge <?=$a['status']?>"><?=$a['status']?></span></td><td><?php if(in_array($a['status'],['pending','checked-in'])):?><details><summary>Complete</summary><form method="post" action="index.php?action=complete_visit"><input type="hidden" name="appointment_id" value="<?=$a['id']?>"><label>Diagnosis<input name="diagnosis" required></label><label>Visit note<textarea name="visit_note"></textarea></label><button class="btn primary">Save</button></form></details><?php elseif($a['status']==='completed'):?><?=htmlspecialchars($a['diagnosis'])?><br><?=htmlspecialchars($a['visit_note'])?><?php endif;?></td></tr><?php endforeach;?></table></section><?php require __DIR__.'/footer.php';?>